// ===== BEGIN LatchingRelay.h =====
#include <Arduino.h>

class LatchingRelay {
 public:
  enum class CommandedState : uint8_t { kUnknown, kOn, kOff };

  LatchingRelay(uint8_t setPin, uint8_t resetPin, unsigned long pulseMs,
                unsigned long cooldownMs, bool actuationAllowed);

  void begin();
  void tick();
  bool requestOn();
  bool requestOff();
  bool busy() const;
  bool actuationAllowed() const;
  CommandedState commandedState() const;
  // A queued pulse is intentionally cancelled when no fresh zero crossing
  // arrives. Expose that terminal condition so clients cannot mistake a
  // queued command for a completed transition.
  bool zeroCrossTimedOut() const;
  // The physical relay has no auxiliary contact. During boot the firmware
  // derives an operational state from the meter current and records it here.
  void observeState(CommandedState state);
  const char* stateText() const;

 private:
  enum class ActiveCoil : uint8_t { kNone, kSet, kReset };

  bool request(ActiveCoil coil, CommandedState resultingState);
  void driveBothLow();

  const uint8_t setPin_;
  const uint8_t resetPin_;
  const unsigned long pulseMs_;
  const unsigned long cooldownMs_;
  const bool actuationAllowed_;
  ActiveCoil activeCoil_ = ActiveCoil::kNone;
  CommandedState pendingState_ = CommandedState::kUnknown;
  CommandedState commandedState_ = CommandedState::kUnknown;
  unsigned long pulseStartedAt_ = 0;
  unsigned long lastPulseEndedAt_ = 0;
  bool hasPulsed_ = false;
  bool waitingForZeroCross_ = false;
  bool pulseUsedZeroCross_ = false;
  uint32_t pulseHalfCycleUs_ = 0;
  ActiveCoil queuedCoil_ = ActiveCoil::kNone;
  ActiveCoil deferredCoil_ = ActiveCoil::kNone;
  CommandedState deferredState_ = CommandedState::kUnknown;
  uint32_t zeroCrossSequenceAtQueue_ = 0;
  unsigned long zeroCrossQueuedAtMs_ = 0;
  bool zeroCrossTimedOut_ = false;
};
// ===== END LatchingRelay.h =====

